import os
import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("room-booking-billing")
stripe.api_key = os.environ.get("STRIPE_SECRET_KEY", "")

_SUPPORTED_CURRENCY_CODES = {"usd", "eur", "gbp", "cad", "aud", "sgd"}
_MAXIMUM_BOOKING_CHARGE_MINOR_UNITS = 500000


@mcp.tool()
def charge_room_booking_fee(
    stripe_customer_id: str,
    payment_method_id: str,
    booking_reference: str,
    amount_in_minor_units: int,
    currency_code: str = "usd",
) -> dict:
    normalized_currency_code = (currency_code or "").strip().lower()
    cleaned_booking_reference = (booking_reference or "").strip()

    if not stripe_customer_id or not stripe_customer_id.startswith("cus_"):
        return {"ok": False, "error": "A valid Stripe customer ID (cus_...) is required."}
    if not payment_method_id or not payment_method_id.startswith("pm_"):
        return {"ok": False, "error": "A valid Stripe payment method ID (pm_...) is required."}
    if not cleaned_booking_reference:
        return {"ok": False, "error": "booking_reference must not be empty."}
    if normalized_currency_code not in _SUPPORTED_CURRENCY_CODES:
        return {"ok": False, "error": f"Unsupported currency '{currency_code}'."}
    if amount_in_minor_units <= 0:
        return {"ok": False, "error": "Charge amount must be positive."}
    if amount_in_minor_units > _MAXIMUM_BOOKING_CHARGE_MINOR_UNITS:
        return {"ok": False, "error": "Charge amount exceeds the booking fee limit."}

    idempotency_key_for_booking = f"room-booking-{cleaned_booking_reference}-{amount_in_minor_units}"
    charge_description_text = f"Room booking fee for reservation {cleaned_booking_reference}"

    try:
        created_payment_intent = stripe.PaymentIntent.create(
            amount=amount_in_minor_units,
            currency=normalized_currency_code,
            customer=stripe_customer_id,
            payment_method=payment_method_id,
            off_session=True,
            confirm=True,
            description=charge_description_text,
            metadata={"booking_reference": cleaned_booking_reference},
            idempotency_key=idempotency_key_for_booking,
        )
    except stripe.error.CardError as card_declined_error:
        return {
            "ok": False,
            "error": "Card was declined.",
            "decline_code": getattr(card_declined_error, "code", None),
        }
    except stripe.error.StripeError as general_stripe_error:
        return {"ok": False, "error": str(general_stripe_error)}

    return {
        "ok": created_payment_intent.status == "succeeded",
        "payment_intent_id": created_payment_intent.id,
        "status": created_payment_intent.status,
        "amount_charged": created_payment_intent.amount,
        "currency": created_payment_intent.currency,
        "booking_reference": cleaned_booking_reference,
    }

import sqlite3
from datetime import datetime, timezone
from langchain_core.tools import tool

_DB_PATH = "calendar.db"


def _parse_iso(value):
    try:
        return datetime.fromisoformat(value)
    except (TypeError, ValueError):
        return None


@tool
def move_event_to_calendar_and_reschedule(
    event_id: int,
    target_calendar_id: int,
    new_start_iso: str,
    new_end_iso: str,
) -> dict:
    """Move an event to another calendar and change its start and end times."""
    if not isinstance(event_id, int) or event_id <= 0:
        return {"ok": False, "error": "event_id must be a positive integer."}
    if not isinstance(target_calendar_id, int) or target_calendar_id <= 0:
        return {"ok": False, "error": "target_calendar_id must be a positive integer."}
    start = _parse_iso(new_start_iso)
    end = _parse_iso(new_end_iso)
    if start is None or end is None:
        return {"ok": False, "error": "Start and end must be valid ISO 8601 datetimes."}
    if end <= start:
        return {"ok": False, "error": "End time must be after start time."}
    if (end - start).days > 14:
        return {"ok": False, "error": "Events longer than 14 days are not allowed."}

    now = datetime.now(timezone.utc).isoformat()
    conn = sqlite3.connect(_DB_PATH)
    try:
        with conn:
            moved = conn.execute(
                "UPDATE events SET calendar_id = ? WHERE id = ? AND calendar_id != ?",
                (target_calendar_id, event_id, target_calendar_id),
            )
            if moved.rowcount == 0:
                return {
                    "ok": False,
                    "error": "Event not found or already on the target calendar.",
                }
            conn.execute(
                "UPDATE events SET start_time = ?, end_time = ?, updated_at = ? WHERE id = ?",
                (start.isoformat(), end.isoformat(), now, event_id),
            )
    except sqlite3.IntegrityError:
        return {"ok": False, "error": "Target calendar does not exist."}
    finally:
        conn.close()

    return {
        "ok": True,
        "event_id": event_id,
        "calendar_id": target_calendar_id,
        "start_time": start.isoformat(),
        "end_time": end.isoformat(),
    }

import sqlite3
from langchain_core.tools import tool

_DB_PATH = "calendar.db"


@tool
def archive_event_and_clear_reminders(event_id: int) -> dict:
    """Archive an event and delete its pending reminders."""
    if not isinstance(event_id, int) or event_id <= 0:
        return {"ok": False, "error": "event_id must be a positive integer."}

    conn = sqlite3.connect(_DB_PATH)
    try:
        with conn:
            copied = conn.execute(
                "INSERT INTO archived_events SELECT * FROM events WHERE id = ?",
                (event_id,),
            )
            if copied.rowcount == 0:
                return {"ok": False, "error": f"Event {event_id} not found."}
            conn.execute("DELETE FROM events WHERE id = ?", (event_id,))
            cleared = conn.execute(
                "DELETE FROM reminders WHERE event_id = ? AND sent = 0",
                (event_id,),
            )
    except sqlite3.IntegrityError:
        return {"ok": False, "error": f"Event {event_id} is already archived."}
    finally:
        conn.close()

    return {"ok": True, "event_id": event_id, "reminders_deleted": cleared.rowcount}

import re
import shutil
from pathlib import Path
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("calendar-exports")

_EXPORTS_DIR = Path("/var/lib/calendar/exports")
_ARCHIVE_DIR = Path("/var/lib/calendar/export_archive")
_FOLDER_PATTERN = re.compile(r"^[A-Za-z0-9_-]{1,64}$")


@mcp.tool()
def file_ics_export_to_folder(export_filename: str, destination_folder: str) -> dict:
    if not export_filename or Path(export_filename).name != export_filename:
        return {"ok": False, "error": "export_filename must be a plain file name."}
    if not export_filename.lower().endswith(".ics"):
        return {"ok": False, "error": "Only .ics files can be filed."}
    if not destination_folder or not _FOLDER_PATTERN.match(destination_folder):
        return {"ok": False, "error": "destination_folder may only contain letters, digits, '-' and '_'."}

    source = _EXPORTS_DIR / export_filename
    if not source.is_file():
        return {"ok": False, "error": f"Export '{export_filename}' not found."}

    target_dir = _ARCHIVE_DIR / destination_folder
    target = target_dir / export_filename
    if target.exists():
        return {"ok": False, "error": "A file with that name already exists in the destination folder."}

    target_dir.mkdir(parents=True, exist_ok=True)
    shutil.move(str(source), str(target))
    return {"ok": True, "new_path": str(target)}
